// Configuration: context for both agents. Edit the values, keep the shape of the returned object.
const payload = $input.first().json.body;
const config = {
  app: 'FiberDoc AI: first-pass review of fiber-optic (outside plant) construction documents',
  audience: 'the engineer and reviewer responsible for this project',
  rules_note: 'The rule catalogue is a NON-AUTHORITATIVE DEMO (invented requirements, not official standards).',
  guardrails: [
    'Never approve, reject or close a finding: humans decide in the FiberDoc review queue.',
    'Use only the findings in the payload. Do not invent values, page numbers or requirements.',
    'If something is unclear, say what a human should check instead of guessing.',
  ],
  owner_roles: ['design engineer', 'construction contractor', 'permitting', 'QA / test', 'reviewer'],
  max_steps: 6,
};
const open = payload.open_findings || [];
return [{ json: { config, payload, has_open_issues: payload.document?.status !== 'error' && open.length > 0 } }];

