// Builds the email: FiberDoc's summary, plus the agent's next steps when it ran.
const { payload: p } = $('Config').first().json;
let think = null, act = null;
try { think = $('Think').first().json.output; act = $('Act').first().json.output; } catch (e) { /* no open issues: AI skipped */ }
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const c = p.counts || {}, doc = p.document || {};
const prefix = p.test ? '[TEST] ' : '';
const subject = doc.status === 'error'
  ? `${prefix}FiberDoc: processing failed for ${doc.name}`
  : `${prefix}FiberDoc: ${doc.name} checked, ${c.failed || 0} failed, ${(c.total || 0) - (c.passed || 0)} open` + (think ? `, risk ${think.risk_level}` : '');
const steps = (act?.next_steps || []).sort((a, b) => a.order - b.order).map((s) =>
  `<li><b>${esc(s.action)}</b><br><span style="color:#666">${esc(s.owner_role)} · ${esc(s.priority)} priority · ${esc((s.rule_ids || []).join(', '))}</span></li>`).join('');
const rows = (p.open_findings || []).map((f) =>
  `<tr><td>${esc(f.rule_id)}</td><td>${esc(f.title)}</td><td>${esc(f.status).replace('_', ' ')}</td><td>${esc(f.severity)}</td></tr>`).join('');
const html = `
${act ? `<p>${esc(act.email_intro)}</p>` : ''}
<p>${esc(p.summary)}</p>
${think ? `<p><b>AI assessment</b> (risk ${esc(think.risk_level)}): ${esc(think.assessment)}</p>` : ''}
${steps ? `<h3>Suggested next steps</h3><ol>${steps}</ol>` : ''}
${(act?.caveats || []).length ? `<p><b>Check before acting:</b></p><ul>${act.caveats.map((x) => `<li>${esc(x)}</li>`).join('')}</ul>` : ''}
${rows ? `<h3>Open findings</h3><table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-size:13px"><tr><th>Rule</th><th>Finding</th><th>Status</th><th>Severity</th></tr>${rows}</table>` : '<p>No open issues.</p>'}
<p><a href="${esc(p.links?.app)}">Open FiberDoc AI</a> to review. The next steps are AI suggestions; findings must be confirmed by a human reviewer and nothing is approved automatically.</p>
<p style="color:#888;font-size:12px">Demo rule catalogue: invented example requirements, not official standards.</p>`;
return [{ json: { to: p.recipient, subject, html } }];
